#include "rinkfit/joint_model.hpp"
#include "rinkfit/joint_effective_input_v1.hpp"
#include <chrono>
#include <iostream>
using namespace rinkfit;using J=eventio::Json;
std::size_t check_material_bindings(const J&binding,const JointEventModel&model,bool hoist){const auto count=binding.at("model_material_prefix_count").get<std::size_t>();if(count>model.materials.size()||binding.at("materials").size()!=count)throw std::runtime_error("material binding prefix size mismatch");std::size_t paths=0;
 auto one=[&](std::size_t i,const J&refinements){const auto&b=binding.at("materials")[i];const auto&actual=model.materials[i];const auto ri=refinements.find(std::to_string(i));const bool refined=ri!=refinements.end()&&ri->at("label")==actual.label&&ri->at("original_path_count")==1&&b.at("paths").size()==1&&ri->contains("original_identity")&&ri->at("original_identity").at("id")==b.at("paths").at(0).at("id");if(b.at("index")!=i||b.at("label")!=actual.label||(!refined&&b.at("paths").size()!=actual.paths.size()))throw std::runtime_error("material identity");for(std::size_t k=0;k<b.at("paths").size();++k){const auto&x=b.at("paths")[k];if(x.at("index")!=k||(!refined&&x.at("id")!=actual.paths[k].id)||x.at("physical_point")!=actual.paths[k].physical_point)throw std::runtime_error("path or fixed entity identity");++paths;}};
 if(hoist){const auto empty=J::object();const auto&refinements=model.source_json.contains("printed_material_path_refinements")?model.source_json.at("printed_material_path_refinements"):empty;for(std::size_t i=0;i<count;++i)one(i,refinements);}else for(std::size_t i=0;i<count;++i){const auto refinements=model.source_json.value("printed_material_path_refinements",J::object());one(i,refinements);}return paths;
}
int main(int argc,char**argv){try{const auto req=JointEffectiveInputV1::strict_json(argv[1]);for(const auto*k:{"packet","model"})eventio::verify(req.at(k).at("file").get<std::string>(),req.at(k).at("sha256"));const auto packet=JointEffectiveInputV1::strict_json(req.at("packet").at("file").get<std::string>());const auto model=JointEventModel::load(req.at("model").at("file"));const auto&binding=packet.at("material_binding");auto time=[&](bool hoist){const auto t=std::chrono::steady_clock::now();const auto paths=check_material_bindings(binding,model,hoist);return J{{"seconds",std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count()},{"paths_checked",paths}};};
 J result={{"schema","rinkfit.actual_material_refinement_invariant_benchmark.v1"},{"model",req.at("model")},{"packet",req.at("packet")},{"materials",model.materials.size()},{"refinement_records",model.source_json.at("printed_material_path_refinements").size()},{"old_value_copy_inside_loop",time(false)},{"new_const_reference_outside_loop",time(true)},{"concurrent_source_numeric_review",true},{"full_cold_qualification_claimed",false},{"solver_started",false}};
 int rejections=0;for(const auto*field:{"label","path_id","fixed_entity"}){auto bad=binding;if(std::string(field)=="label")bad["materials"][0]["label"]="wrong source entity";else if(std::string(field)=="path_id")bad["materials"][0]["paths"][0]["id"]="wrong finite path";else bad["materials"][0]["paths"][0]["physical_point"]=!bad["materials"][0]["paths"][0]["physical_point"].get<bool>();for(bool hoist:{false,true}){bool rejected=false;try{check_material_bindings(bad,model,hoist);}catch(const std::exception&){rejected=true;}if(!rejected)throw std::runtime_error("identity mutation accepted");++rejections;}}
 if(result.at("old_value_copy_inside_loop").at("paths_checked")!=result.at("new_const_reference_outside_loop").at("paths_checked"))throw std::runtime_error("path denominator differs");result["strict_identity_mutation_rejections"]=rejections;result["passed"]=true;eventio::atomic_json(argv[2],result);std::cout<<result.dump()<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 2;}}
